SELECT n.nspname AS schema_name, o.relname AS object_name, COALESCE(d.description, '') AS text FROM pg_class o JOIN pg_namespace n ON n.oid = o.relnamespace LEFT JOIN pg_description d ON d.objoid = o.oid AND d.classoid = 'pg_class'::regclass AND d.objsubid = 0 WHERE d.description IS NOT NULL AND n.nspname = :schema AND o.relkind IN ('r', 'm') ORDER BY n.nspname, o.relname;
